content.css:
.ganttChart {
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
}
.ganttChart .chartContainer rect.gantt-bar {
  transition: opacity 0.2s ease;
  cursor: pointer;
}
.ganttChart .chartContainer rect.gantt-bar:hover {
  opacity: 0.9 !important;
}
.ganttChart .chartContainer rect.gantt-bar:focus {
  outline: 2px solid #0078d4;
  outline-offset: 2px;
}
.ganttChart .chartContainer rect.gantt-progress {
  pointer-events: none;
}
.ganttChart .chartContainer .data-label {
  pointer-events: none;
  cursor: default;
}
.ganttChart .chartContainer .today-line {
  pointer-events: none;
}
.ganttChart .chartContainer .grid-line {
  pointer-events: none;
}
.ganttChart .chartContainer .x-axis,
.ganttChart .chartContainer .y-axis {
  font-size: 10px;
}
.ganttChart.landing rect:first-child {
  cursor: default;
}
.ganttChart.landing rect:first-child:hover {
  opacity: 1;
}
@media screen and (-ms-high-contrast: active) {
  .ganttChart rect {
    stroke: currentColor;
    stroke-width: 1px;
  }
  .ganttChart line {
    stroke: currentColor !important;
  }
  .ganttChart text {
    fill: currentColor;
  }
}
